import React, { useState, useEffect } from 'react';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import './Simulador.css';

// Fix for default markers
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require('leaflet/dist/images/marker-icon-2x.png'),
  iconUrl: require('leaflet/dist/images/marker-icon.png'),
  shadowUrl: require('leaflet/dist/images/marker-shadow.png'),
});

// Custom airplane icon
const airplaneIcon = new L.DivIcon({
  className: 'airplane-marker',
  html: '<i class="fas fa-plane" style="color: #007bff; font-size: 16px; transform: rotate(45deg);"></i>',
  iconSize: [20, 20],
  iconAnchor: [10, 10]
});

// Custom airport icon
const airportIcon = new L.DivIcon({
  className: 'airport-marker',
  html: '<i class="fas fa-map-marker-alt" style="color: #dc3545; font-size: 20px;"></i>',
  iconSize: [25, 25],
  iconAnchor: [12, 25]
});

const Simulador = () => {
  const [flights, setFlights] = useState([]);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [elapsedTime, setElapsedTime] = useState(0);
  const [isRunning, setIsRunning] = useState(false);
  const [speed, setSpeed] = useState(1);
  const [simulationStatus, setSimulationStatus] = useState('Monitoreo en tiempo real activo');
  const [activeView, setActiveView] = useState('flights');
  const [showRoutes, setShowRoutes] = useState(false);

  const airports = [
    { name: "Madrid", lat: 40.4168, lng: -3.7038, capacity: 850, packages: 697 },
    { name: "París", lat: 48.8566, lng: 2.3522, capacity: 750, packages: 580 },
    { name: "Londres", lat: 51.5074, lng: -0.1278, capacity: 900, packages: 720 },
    { name: "Roma", lat: 41.9028, lng: 12.4964, capacity: 650, packages: 450 },
    { name: "Berlín", lat: 52.5200, lng: 13.4050, capacity: 700, packages: 520 },
    { name: "Viena", lat: 48.2082, lng: 16.3738, capacity: 850, packages: 697 },
    { name: "Ámsterdam", lat: 52.3676, lng: 4.9041, capacity: 800, packages: 640 },
    { name: "Barcelona", lat: 41.3851, lng: 2.1734, capacity: 600, packages: 480 }
  ];

  useEffect(() => {
    if (isRunning) {
      const interval = setInterval(() => {
        setCurrentTime(new Date());
        setElapsedTime(prev => prev + speed);

        // Generate random flights
        if (Math.random() < 0.3) {
          const origin = airports[Math.floor(Math.random() * airports.length)];
          const destination = airports[Math.floor(Math.random() * airports.length)];

          if (origin !== destination) {
            const newFlight = {
              id: Date.now() + Math.random(),
              origin: origin.name,
              destination: destination.name,
              lat: origin.lat + (destination.lat - origin.lat) * Math.random(),
              lng: origin.lng + (destination.lng - origin.lng) * Math.random(),
              progress: Math.random() * 100
            };

            setFlights(prev => [...prev.slice(-50), newFlight]);
          }
        }
      }, 1000 / speed);

      return () => clearInterval(interval);
    }
  }, [isRunning, speed, airports]);

  const handlePlay = () => {
    setIsRunning(true);
    setSimulationStatus('Simulación en ejecución');
  };

  const handlePause = () => {
    setIsRunning(false);
    setSimulationStatus('Simulación pausada');
  };

  const handleStop = () => {
    setIsRunning(false);
    setFlights([]);
    setElapsedTime(0);
    setSimulationStatus('Simulación detenida');
  };

  const handleSpeedChange = () => {
    const speeds = [1, 2, 5, 10];
    const currentIndex = speeds.indexOf(speed);
    const nextSpeed = speeds[(currentIndex + 1) % speeds.length];
    setSpeed(nextSpeed);
  };

  const handleRestart = () => {
    setIsRunning(false);
    setFlights([]);
    setElapsedTime(0);
    setCurrentTime(new Date());
    setSimulationStatus('Sistema reiniciado');
    setTimeout(() => {
      setSimulationStatus('Monitoreo en tiempo real activo');
    }, 2000);
  };

  const formatTime = (seconds) => {
    const hrs = Math.floor(seconds / 3600);
    const mins = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    return `${hrs.toString().padStart(2, '0')} : ${mins.toString().padStart(2, '0')} : ${secs.toString().padStart(2, '0')}`;
  };

  const getSaturation = () => {
    const totalCapacity = airports.reduce((sum, airport) => sum + airport.capacity, 0);
    const totalPackages = airports.reduce((sum, airport) => sum + airport.packages, 0);
    return ((totalPackages / totalCapacity) * 100).toFixed(2);
  };

  const getMostSaturatedAirport = () => {
    return airports.reduce((max, airport) => {
      const saturation = (airport.packages / airport.capacity) * 100;
      const maxSaturation = (max.packages / max.capacity) * 100;
      return saturation > maxSaturation ? airport : max;
    });
  };

  return (
    <div className="section-content active" id="simulationSection">
      {/* Sidebar Navigation for Simulation */}
      <div className="simulation-sidebar">
        <div className="sidebar-header">
          <h3><i className="fas fa-cogs"></i> Modos de Operación</h3>
        </div>
        <div className="sidebar-menu">
          <button className="sidebar-item active" data-mode="realtime">
            <i className="fas fa-broadcast-tower"></i>
            <span>Monitoreo en Tiempo Real</span>
          </button>
          <button className="sidebar-item disabled" data-mode="weekly" disabled>
            <i className="fas fa-calendar-week"></i>
            <span>Simulación Semanal</span>
            <small>Próximamente</small>
          </button>
          <button className="sidebar-item disabled" data-mode="collapse" disabled>
            <i className="fas fa-exclamation-triangle"></i>
            <span>Simulación de Colapso</span>
            <small>Próximamente</small>
          </button>
        </div>
      </div>

      {/* Main Simulation Content */}
      <div className="simulation-main-content">
        <div className="control-panel">
          <h2>Monitoreo en Tiempo Real</h2>
          <div className="status-section">
            <span className="status-label">Estado de la Simulación:</span>
            <span className="status-text" id="simulationStatus">{simulationStatus}</span>
          </div>

          {/* Simulation Controls */}
          <div className="simulation-controls">
            <h3><i className="fas fa-cogs"></i> Simulación</h3>
            <div className="control-buttons">
              <button className="sim-control-btn play-btn" id="playBtn" onClick={handlePlay}>
                <i className="fas fa-play"></i> Iniciar
              </button>
              <button className="sim-control-btn pause-btn" id="pauseBtn" onClick={handlePause}>
                <i className="fas fa-pause"></i> Pausar
              </button>
              <button className="sim-control-btn stop-btn" id="stopBtn" onClick={handleStop}>
                <i className="fas fa-stop"></i> Detener
              </button>
              <button className="sim-control-btn speed-btn" id="speedBtn" onClick={handleSpeedChange}>
                <i className="fas fa-tachometer-alt"></i> {speed}x
              </button>
              <button className="sim-control-btn restart-btn" id="restartBtn" onClick={handleRestart}>
                <i className="fas fa-redo-alt"></i> Reiniciar Todo
              </button>
            </div>
          </div>
        </div>

        {/* Map Area */}
        <div className="map-container">
          <div className="map-area">
            <MapContainer
              center={[48.8566, 2.3522]}
              zoom={5}
              className="flight-map"
              id="map"
            >
              <TileLayer
                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
              />

              {/* Show airports */}
              {(activeView === 'airports' || activeView === 'flights') && airports.map((airport, index) => (
                <Marker 
                  key={index} 
                  position={[airport.lat, airport.lng]} 
                  icon={airportIcon}
                >
                  <Popup>
                    <div>
                      <strong>{airport.name}</strong><br/>
                      Capacidad: {airport.capacity}<br/>
                      Paquetes: {airport.packages}<br/>
                      Saturación: {((airport.packages / airport.capacity) * 100).toFixed(2)}%
                    </div>
                  </Popup>
                </Marker>
              ))}

              {/* Show flights */}
              {activeView === 'flights' && flights.map((flight) => (
                <Marker 
                  key={flight.id} 
                  position={[flight.lat, flight.lng]} 
                  icon={airplaneIcon}
                >
                  <Popup>
                    <div>
                      <strong>Vuelo {flight.id.toString().slice(-4)}</strong><br/>
                      Origen: {flight.origin}<br/>
                      Destino: {flight.destination}<br/>
                      Progreso: {flight.progress.toFixed(1)}%
                    </div>
                  </Popup>
                </Marker>
              ))}
            </MapContainer>

            {/* Map Controls */}
            <div className="map-controls-bottom">
              <button 
                className={`map-btn vuelos-btn ${activeView === 'flights' ? 'active' : ''}`}
                data-view="flights"
                onClick={() => setActiveView('flights')}
              >
                <i className="fas fa-plane"></i>
                Vuelos
              </button>
              <button 
                className={`map-btn rutas-btn ${activeView === 'routes' ? 'active' : ''}`}
                data-view="routes"
                onClick={() => setActiveView('routes')}
              >
                <i className="fas fa-route"></i>
                Rutas
              </button>
              <button 
                className={`map-btn aeropuertos-btn ${activeView === 'airports' ? 'active' : ''}`}
                data-view="airports"
                onClick={() => setActiveView('airports')}
              >
                <i className="fas fa-map-marker-alt"></i>
                Aeropuertos
              </button>
              <button 
                className="map-btn mostrar-linea-btn"
                onClick={() => setShowRoutes(!showRoutes)}
              >
                Mostrar Línea
              </button>
            </div>
          </div>

          {/* Info Panel */}
          <div className="info-panel">
            <div className="info-header">
              <h3>Más información</h3>
              <button className="close-btn">
                <i className="fas fa-times"></i>
              </button>
            </div>

            <div className="time-section">
              <div className="current-time">
                <label>Hora actual:</label>
                <div className="time-display" id="currentTimeDisplay">
                  {currentTime.toLocaleDateString('es-ES')}, {currentTime.toLocaleTimeString('es-ES')}
                </div>
              </div>

              <div className="elapsed-time">
                <label>Tiempo transcurrido:</label>
                <div className="time-counter" id="timeCounter">{formatTime(elapsedTime)}</div>
              </div>
            </div>

            <div className="stats-section">
              <div className="stat-row">
                <span className="stat-label">Vuelos en el aire:</span>
                <span className="stat-value" id="flightsCount">{flights.length}</span>
              </div>

              <div className="stat-row">
                <span className="stat-label">Saturación de aviones:</span>
                <span className="stat-value" id="planeSaturationValue">{((flights.length / 500) * 100).toFixed(2)}%</span>
              </div>

              <div className="stat-row">
                <span className="stat-label">Saturación de aeropuertos:</span>
                <span className="stat-value" id="airportSaturationValue">{getSaturation()}%</span>
              </div>
            </div>

            <div className="airport-section">
              <h4>Aeropuertos más saturados</h4>
              <div className="airport-info" id="saturatedAirports">
                {(() => {
                  const mostSaturated = getMostSaturatedAirport();
                  const saturation = ((mostSaturated.packages / mostSaturated.capacity) * 100).toFixed(2);
                  return (
                    <>
                      <div className="airport-name">{mostSaturated.name}</div>
                      <div className="airport-details">
                        <div>Capacidad: {mostSaturated.capacity}</div>
                        <div>Paquetes: {mostSaturated.packages}</div>
                        <div className="saturation-highlight">Saturación: {saturation}%</div>
                      </div>
                    </>
                  );
                })()}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Simulador;
